#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct { float x, y, z; } Vector;
typedef struct { Vector origin, dir; } Ray;
typedef struct { Vector point, normal; float t; int hit; } Hit;

static Vector vec(float x, float y, float z){ Vector v; v.x=x; v.y=y; v.z=z; return v; }

static Vector vsub(Vector a, Vector b){ return vec(a.x-b.x, a.y-b.y, a.z-b.z); }

static float vdot(Vector a, Vector b){ return a.x*b.x + a.y*b.y + a.z*b.z; }

static Vector vnorm(Vector v){
    float len = sqrtf(v.x*v.x + v.y*v.y + v.z*v.z);
    return vec(v.x/len, v.y/len, v.z/len);
}

static Ray ray_create(Vector o, Vector d){ Ray r; r.origin=o; r.dir=vnorm(d); return r; }

static Vector ray_at(Ray r, float t){
    return vec(r.origin.x + r.dir.x*t, r.origin.y + r.dir.y*t, r.origin.z + r.dir.z*t);
}

static Hit sphere_intersect(Ray r, Vector c, float radius){
    Hit h; h.hit=0; h.point=vec(0,0,0); h.normal=vec(0,0,0); h.t=0.0f;
    Vector oc = vsub(r.origin, c);
    float a = vdot(r.dir, r.dir);
    float b = 2.0f * vdot(oc, r.dir);
    float cc = vdot(oc, oc) - radius*radius;
    float disc = b*b - 4*a*cc;
    if (disc < 0) return h;
    float t = (-b - sqrt(disc)) / (2*a);
    if (t < 0.001f){ t = (-b + sqrt(disc)) / (2*a); if (t < 0.001f) return h; }
    h.point = ray_at(r, t);
    h.normal = vnorm(vsub(h.point, c));
    h.t = t; h.hit = 1;
    return h;
}

static Vector sky_color(Ray r){
    float t = (r.dir.y + 1.0f) * 0.5f;
    float o = 1.0f - t;
    return vec(0.5f*t + o, 0.7f*t + o, o + t);
}

static Vector trace(Ray ray, Vector light){
    Vector sc = vec(0.0f, -0.5f, -5.0f);
    Hit hs = sphere_intersect(ray, sc, 1.0f);
    int plane = 0; float tp = 0.0f; Vector pp = vec(0,0,0);
    if (fabsf(ray.dir.y) >= 0.0001f){
        tp = (-1.5f - ray.origin.y) / ray.dir.y;
        if (tp >= 0.001f){ plane = 1; pp = ray_at(ray, tp); }
    }
    int obj; Vector point, normal;
    if (hs.hit && (!plane || hs.t < tp)){ obj=0; point=hs.point; normal=hs.normal; }
    else if (plane){ obj=1; point=pp; normal=vec(0.0f,1.0f,0.0f); }
    else return sky_color(ray);

    Ray sray = ray_create(point, light);
    Hit sh = sphere_intersect(sray, sc, 1.0f);
    float intensity;
    if (sh.hit) intensity = 0.2f;
    else intensity = (float)fmax((double)vdot(normal, light), 0.0) * 0.8f + 0.2f;

    if (obj==0) return vec(intensity, intensity*0.2f, intensity*0.2f);
    float c = (((int)floorf(point.x) + (int)floorf(point.z)) & 1) ? 0.4f : 0.9f;
    return vec(c*intensity, c*intensity, c*intensity);
}

static Vector **allocate_image(int w, int h){
    Vector **img = malloc(h * sizeof(Vector*));
    for (int y=0; y<h; y++) img[y] = malloc(w * sizeof(Vector));
    return img;
}

static void write_image(const char *name, Vector **img, int w, int h){
    FILE *fp = fopen(name, "w");
    if (!fp){ fprintf(stderr, "Error: could not open %s\n", name); return; }
    fprintf(fp, "P3\n%d %d\n255\n", w, h);
    for (int y=0; y<h; y++){
        for (int x=0; x<w; x++){
            Vector p = img[y][x];
            float ch[3] = { p.x, p.y, p.z };
            int v[3];
            for (int k=0; k<3; k++){
                double d = fmax((double)ch[k], 0.0);
                d = fmin(d, 1.0);
                v[k] = (int)((float)d * 255.99f);
            }
            fprintf(fp, "%d %d %d\n", v[0], v[1], v[2]);
        }
    }
    fclose(fp);
    fprintf(stderr, "Wrote image to %s\n", name);
}

int main(void){
    int W = 800, H = 600;
    fprintf(stderr, "Creating high-resolution image: %dx%d\n", W, H);
    fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");
    Vector light = vnorm(vec(1.0f, 1.0f, -1.0f));
    Vector **img = allocate_image(W, H);
    fprintf(stderr, "Rendering high-resolution image...\n");
    float aspect = (float)W / (float)H;
    Vector origin = vec(0.0f, 0.0f, 0.0f);
    for (int y=0; y<H; y++){
        fprintf(stderr, "\rProgress: %.1f%%", 100.0f*(float)y/600.0f);
        for (int x=0; x<W; x++){
            float u = (float)x / 799.0f;
            float v = (float)y / 599.0f;
            Vector dir = vec((2.0f*u - 1.0f)*aspect, 2.0f*(1.0f - v) - 1.0f, -1.0f);
            Ray ray = ray_create(origin, dir);
            img[y][x] = trace(ray, light);
        }
    }
    fprintf(stderr, "\nRendering complete\n");
    write_image("image.ppm", img, W, H);
    fprintf(stderr, "Done.\n");
    return 0;
}

